#include <iostream>
#include <climits>
#include <numeric>
int main(){long long a[2][10]={{10000001,10000001,10000001,1,1025785,1025785,7018082,7018082,7018082,6269720},{10000001,10000001,10000001,7018082,7018082,7018082,1,1025785,1025785,6269720}};long long sum[2][1024]={},res[2][1024]={};for(int t=0;t<2;t++)for(int m=1;m<1024;m++){long long mi=LLONG_MAX;for(int g=0;g<10;g++)if(m>>g&1){sum[t][m]+=a[t][g];mi=std::min(mi,a[t][g]);}res[t][m]=sum[t][m]-mi;}long long bn=LLONG_MAX,bd=1;int best=0;bool have=false;for(int code=0;code<(1<<20);code++){int m[4]={},v=code;for(int g=0;g<10;g++,v>>=2)m[v&3]|=1<<g;long long rn=1,rd=1;bool inf=false;for(int i=0;i<4;i++)for(int j=0;j<4;j++){long long u=res[i/2][m[i]],w=sum[i/2][m[j]];if(!w&&u){inf=true;continue;}if(w&&u*rd>rn*w){rn=u;rd=w;}}if(!inf&&(!have||(__int128)rn*bd<(__int128)bn*rd)){have=true;bn=rn;bd=rd;best=code;}}long long g=std::gcd(bn,bd);std::cout<<"{\"allocations\":1048576,\"best_numerator\":"<<bn/g<<",\"best_denominator\":"<<bd/g<<",\"best_encoding\":"<<best<<",\"exceeds_11_over_10\":"<<(bn*10>bd*11?"true":"false")<<"}\n";}
